mapper.select:
SELECT task_id, SUM(minutes) AS minutes, COUNT(*) AS cnt, MAX(ended_at) AS last_at
FROM time_log
WHERE workspace_id = #{workspaceId} AND user_id = #{userId}
  AND ended_at IS NOT NULL
  AND started_at >= #{from} AND started_at < #{to}
GROUP BY task_id

SELECT t.req_id, r.name AS req_name, DATE(tl.started_at) AS day, SUM(tl.minutes) AS minutes FROM time_log tl LEFT JOIN task t ON t.id = tl.task_id AND t.workspace_id = tl.workspace_id LEFT JOIN requirement r ON r.id = t.req_id AND r.workspace_id = t.workspace_id WHERE tl.workspace_id = #{workspaceId} AND tl.user_id = #{userId} AND tl.ended_at IS NOT NULL AND tl.started_at >= #{from} AND tl.started_at < #{to}
AND (t.req_id IS NULL OR NOT EXISTS ( SELECT 1 FROM project_member pm WHERE pm.workspace_id = t.workspace_id AND pm.project_id = t.req_id AND pm.user_id = #{viewerId} AND pm.access = 'none'))
GROUP BY t.req_id, r.name, DATE(tl.started_at)

SELECT COUNT(*) FROM time_log
WHERE workspace_id = #{workspaceId} AND user_id = #{userId}
  AND ended_at IS NOT NULL
  AND started_at >= #{from} AND started_at < #{to}

SELECT p.id AS plan_id, p.name, p.req_id, r.name AS req_name, p.status, p.updated_at, (SELECT COUNT(*) FROM test_plan_case pc WHERE pc.plan_id = p.id AND pc.executed_by_user_id = #{userId} AND pc.executed_at >= #{from} AND pc.executed_at < #{to}) AS executed_count FROM test_plan p LEFT JOIN requirement r ON r.id = p.req_id AND r.workspace_id = p.workspace_id WHERE p.workspace_id = #{workspaceId} AND p.executor_user_id = #{userId} AND p.status = 'done' AND p.updated_at >= #{from} AND p.updated_at < #{to}
AND NOT EXISTS ( SELECT 1 FROM project_member pm WHERE pm.workspace_id = p.workspace_id AND pm.project_id = p.req_id AND pm.user_id = #{viewerId} AND pm.access = 'none')
ORDER BY p.updated_at DESC LIMIT 20

SELECT id, session_id, draft_key, kind, action, answer, title, payload_json, created_at, updated_at
FROM catchup_decision
WHERE session_id = #{sessionId}

SELECT id, session_id, row_key, day, req_id, minutes, created_at
FROM catchup_time_alloc
WHERE session_id = #{sessionId}

mapper.update:
UPDATE task
SET is_blocked = #{blocked}, blocked_reason = #{reason}
WHERE workspace_id = #{workspaceId} AND id = #{taskId}

mapper.select:
SELECT c.id, c.from_session_id, c.to_week_start, c.task_id, c.item_no, c.title,
       c.project_name, c.type_label, c.status_label, c.minutes, c.reason, c.created_at
FROM catchup_carry c
JOIN catchup_session s ON s.id = c.from_session_id
JOIN task t ON t.id = c.task_id AND t.workspace_id = s.workspace_id AND t.deleted_at IS NULL
WHERE s.workspace_id = #{workspaceId}
  AND s.user_id = #{userId}
  AND s.status = 'submitted'
  AND c.to_week_start = #{toWeekStart}

mapper.delete:
DELETE c FROM catchup_carry c
JOIN catchup_session s ON s.id = c.from_session_id
WHERE s.workspace_id = #{workspaceId}
  AND s.user_id = #{userId}
  AND c.to_week_start < #{beforeWeek}
